package com.termux.app.workspace;
import android.app.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiHistoryCloseTest {
 Activity activity;LocalAiUi ui;ExecutorService worker;LocalAiFiles files;
 @Before public void setup()throws Exception{activity=Robolectric.buildActivity(Activity.class).setup().get();ui=new LocalAiUi(activity);Field f=LocalAiUi.class.getDeclaredField("worker");f.setAccessible(true);worker=(ExecutorService)f.get(ui);files=new LocalAiFiles(activity);}
 @After public void close(){ui.close();}
 WorkspaceStore.Session profile(String chat){WorkspaceStore.Session s=new WorkspaceStore.Session();s.localAi=true;s.environment="termux";s.localChat=chat;return s;}
 void settle()throws Exception{worker.submit(()->{}).get(5,TimeUnit.SECONDS);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 @Test public void deletionWaitsForQueuedHistoryWriterAndDoesNotReappear()throws Exception{
  WorkspaceStore.Session s=profile("queued-history");ui.panel(s,()->{});settle();files.saveHistory(s.localChat,new JSONArray());CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);worker.submit(()->{entered.countDown();try{release.await(5,TimeUnit.SECONDS);files.saveHistory(s.localChat,new JSONArray().put(new JSONObject().put("text","last write")));}catch(Exception e){throw new RuntimeException(e);}});assertTrue(entered.await(3,TimeUnit.SECONDS));AtomicBoolean done=new AtomicBoolean();ui.closeWithHistory(s,false,()->done.set(true));assertTrue(ui.closing(s.id));assertTrue(new File(files.chats,s.localChat+".json").exists());release.countDown();settle();assertTrue(done.get());assertFalse(ui.closing(s.id));assertFalse(new File(files.chats,s.localChat+".json").exists());settle();assertFalse(new File(files.chats,s.localChat+".json").exists());
 }
 @Test public void anotherOpenReferenceBlocksDeletingSharedHistory()throws Exception{WorkspaceStore.Session a=profile("shared-history"),b=profile("shared-history");files.saveHistory(a.localChat,new JSONArray());ui.panel(a,()->{});ui.panel(b,()->{});settle();AtomicBoolean done=new AtomicBoolean();ui.closeWithHistory(a,false,()->done.set(true));settle();assertFalse(done.get());assertTrue(ui.active(a.id));assertTrue(new File(files.chats,a.localChat+".json").exists());}
 @Test public void keepingHistoryClosesPanelWithoutDeletingChat()throws Exception{WorkspaceStore.Session s=profile("kept-history");files.saveHistory(s.localChat,new JSONArray());ui.panel(s,()->{});settle();AtomicBoolean done=new AtomicBoolean();ui.closeWithHistory(s,true,()->done.set(true));settle();assertTrue(done.get());assertFalse(ui.active(s.id));assertTrue(new File(files.chats,s.localChat+".json").exists());}
}
